var i=`0634-fattah`;var n=`world-0634`;var a=`EG`;var r=`northern-africa`;var o=4;var s=106;var l={en:`Fattah`,ua:`Фатта`};var d={en:`Fattah is a Egypt classic prepared with white rice, pita bread, lamb, garlic. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Фатта, страва кухні країни Єгипет зі складниками: білий рис, піта, ягнятина, часник. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var g=[{en:`Cook the listed ingredients in simmering water for about 20 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 20 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:20,i:[[`white-rice`,300,`g`],[`water`,560,`ml`]]},{en:`Roast in a preheated 190°C oven for about 14 minutes until nicely browned and fully cooked; turn once if needed.`,ua:`Запікайте в розігрітій до 190°C духовці приблизно 14 хвилин до рум’яності й готовності; за потреби переверніть.`,t:[`roasting`],m:14,i:[[`pita-bread`,250,`g`],[`extra-virgin-olive-oil`,35,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 55 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 55 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:55,i:[[`lamb`,650,`g`],[`beef-stock`,850,`ml`],[`garlic`,5,`clove`]]},{en:`Cook the listed sauce ingredients over medium-low heat for about 12 minutes until aromatic and slightly thickened.`,ua:`Готуйте складники соусу на помірно слабкому вогні приблизно 12 хвилин до появи аромату та легкого загустіння.`,t:[`sauteing`,`reducing-sauce`],m:12,i:[[`white-vinegar`,28,`ml`],[`tomato`,320,`g`]]},{en:`Pour hot garlic-vinegar tomato sauce over toasted bread, spoon on rice and tender meat; moisten with stock without drowning the dish.`,ua:`Полийте підсмажений хліб гарячим часниково-оцтовим томатним соусом, додайте рис і ніжне м’ясо; зволожте бульйоном без надлишку рідини.`,t:[`layered-assembly`,`garnishing`],m:5,i:[[`parsley`,20,`g`]]}];var u={slug:i,id:n,country:`EG`,region:r,servings:4,minutes:106,title:l,text:d,steps:g};export{a as country,u as default,n as id,s as minutes,r as region,o as servings,i as slug,g as steps,d as text,l as title};